import React, { createContext, useContext, useEffect, useState } from 'react';
import io from 'socket.io-client';
import { useAuth } from './AuthContext';

const ChatContext = createContext();

export const ChatProvider = ({ children }) => {
  const { user, token } = useAuth();
  const [socket, setSocket] = useState(null);
  const [channels, setChannels] = useState([]);
  const [currentChannel, setCurrentChannel] = useState(null);
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    if (user && token) {
      const newSocket = io('http://localhost:5000', { auth: { token } });
      newSocket.on('connect', () => console.log('Connected to chat'));
      newSocket.on('new-message', (msg) => setMessages(prev => [...prev, msg]));
      setSocket(newSocket);
      return () => newSocket.close();
    }
  }, [user, token]);

  const joinChannel = (channelId) => {
    if (socket) {
      socket.emit('join-channel', channelId);
      setCurrentChannel(channelId);
      // TODO: fetch previous messages
    }
  };

  const sendMessage = (content) => {
    if (socket && currentChannel) {
      socket.emit('send-message', { channelId: currentChannel, content });
    }
  };

  return (
    <ChatContext.Provider value={{ channels, currentChannel, messages, joinChannel, sendMessage }}>
      {children}
    </ChatContext.Provider>
  );
};

export const useChat = () => useContext(ChatContext);
